# -*- perl -*-
## [:check_threshold]
## check a value against a configurable threshold
##
## Usage:
##   $code{'check_threshold'}->( { value => 42 } );
## Returns: { mode => qw| true |, data => 1 } if under threshold
##          { mode => qw| false |, data => "exceeded" } if over

use strict;
use warnings;

sub main {
    my $self = shift;

    my $config = $self->{config} || {};
    my $threshold = 30;

    ## read threshold from config with default of 30
    if ( exists $config->{threshold} ) {
        $threshold = $config->{threshold};
    }

    ## get the value to check
    my $value = shift @_;
    $value = 0 if !defined $value;

    ## check if value exceeds threshold
    if ( $value > $threshold ) {
        my $msg = sprintf(
            "value %d exceeds threshold %d",
            $value,
            $threshold,
        );

        ## log warning (level 1)
        <[base.logs]>()->( 1, $msg );

        return { mode => qw| false |, data => "exceeded" };
    }

    return { mode => qw| true |, data => 1 };
}

1;
